describe('File Upload Confirmation', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully upload a small text file and display confirmation', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Verify file input is visible
    cy.get('[id="file-upload"]').should('be.visible');

    // Select a small text file
    cy.get('[id="file-upload"]').selectFile('cypress/fixtures/sample-text.txt', { force: true });

    // Verify file is selected
    cy.get('[id="file-upload"]').should('have.value');

    // Click the submit button
    cy.get('[id="file-submit"]').click();

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify success message appears
    cy.get('[id="flash-messages"]').should('contain', 'File uploaded successfully');

    // Verify file name is displayed
    cy.get('[id="uploaded-files"]').should('be.visible');
    cy.get('[id="uploaded-files"]').should('contain', 'sample-text.txt');

    // Verify page header confirms upload
    cy.get('[id="page-header"]').should('contain', 'File Uploaded!');
  });

  it('should handle empty file selection and display error message', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Verify file input is visible
    cy.get('[id="file-upload"]').should('be.visible');

    // Clear file input
    cy.get('[id="file-upload"]').clear();

    // Verify file input is empty
    cy.get('[id="file-upload"]').should('have.value');

    // Click the submit button
    cy.get('[id="file-submit"]').click();

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify error message appears
    cy.get('[id="flash-messages"]').should('contain', 'Please select a file to upload');

    // Verify file name is not displayed
    cy.get('[id="uploaded-files"]').should('not.exist');

    // Verify page header does not show success message
    cy.get('[id="page-header"]').should('not.contain', 'File Uploaded!');
  });
});
